begin;
select d.id,l.legacy_source_category_id,m.mapping_status,d.decision_status,m.mapping_status is distinct from d.decision_status,case when m.mapping_status is distinct from d.decision_status then 'new canonical decision preserves legacy and records recommended status' else 'legacy status retained' end,m.policy_version,'taxonomy-final-2026-08-03',jsonb_build_object('matching_method',l.matching_method,'conflict_type',l.conflict_type)
from fitmatch_taxonomy.legacy_identity_links l join fitmatch_taxonomy.classification_decisions d on d.source_category_id=l.source_category_id and d.policy_version='taxonomy-final-2026-08-03' left join public.source_category_mappings m on m.source_category_id=l.legacy_source_category_id on conflict do nothing;
select d.id,d.garment_type_code,case when d.decision_status='unsupported' then 'current_app_category' end,'current_app_detail','independent_axis_review','comparison_family_review','measurement_policy_review',coalesce(d.garment_type_code,'unknown_apparel'),'medium','normal','review_required','taxonomy-final-2026-08-03'
from fitmatch_taxonomy.classification_decisions d where d.policy_version='taxonomy-final-2026-08-03' and d.app_support_status in('transform_required','unsupported_by_current_app') on conflict(decision_id) do nothing;
commit;
